<?php
declare(strict_types=1);
require_once __DIR__ . '/../includes/bootstrap.php'; require_once __DIR__ . '/../includes/auth.php';
$user=current_user(); if(!$user||!in_array($user['role'],['Administrator','Bursar'],true)){http_response_code(403);exit('Access denied.');}
if($_SERVER['REQUEST_METHOD']!=='POST'||!verify_csrf()){http_response_code(419);exit('This form has expired.');}
$staff=filter_var($_POST['staff_id']??null,FILTER_VALIDATE_INT);$salary=$_POST['base_salary']??null;$currency=(string)($_POST['currency']??'');$effective=trim((string)($_POST['effective_from']??''));
$d=DateTimeImmutable::createFromFormat('!Y-m-d',$effective);$e=DateTimeImmutable::getLastErrors();$dateOk=$d!==false&&$d->format('Y-m-d')===$effective&&($e===false||(!$e['warning_count']&&!$e['error_count']));
if(!$staff||!is_numeric($salary)||(float)$salary<0||(float)$salary>9999999999.99||!in_array($currency,['USD','ZiG'],true)||!$dateOk){$_SESSION['error']='Enter a valid salary, currency and effective date.';header('Location: ../?page=payroll&tab=staff');exit;}
$pdo=db();try{$pdo->beginTransaction();$q=$pdo->prepare("SELECT id FROM users WHERE id=:id AND active=1 AND role IN ('Administrator','Head','Teacher','Bursar','Clerk') FOR UPDATE");$q->execute(['id'=>$staff]);if(!$q->fetch())throw new DomainException('Select an active staff account.');$q=$pdo->prepare('INSERT INTO staff_pay_settings(staff_id,base_salary,currency,effective_from,active,updated_by) VALUES(:staff,:salary,:currency,:effective,1,:user) ON DUPLICATE KEY UPDATE base_salary=VALUES(base_salary),currency=VALUES(currency),effective_from=VALUES(effective_from),active=1,updated_by=VALUES(updated_by)');$q->execute(['staff'=>$staff,'salary'=>number_format((float)$salary,2,'.',''),'currency'=>$currency,'effective'=>$effective,'user'=>$user['id']]);audit_log('payroll.salary_setting_saved','staff_pay_settings',(int)$staff,['currency'=>$currency,'effective_from'=>$effective]);$pdo->commit();$_SESSION['notice']='Staff salary setting saved.';}catch(Throwable $x){if($pdo->inTransaction())$pdo->rollBack();error_log('Payroll salary save failed: '.$x->getMessage());$_SESSION['error']=$x instanceof DomainException?$x->getMessage():'Could not save salary setting.';}
header('Location: ../?page=payroll&tab=staff');exit;
